I & =\oiint\limits_S x^3 \mathrm{d} y \mathrm{d} z+y^3 \mathrm{d} z \mathrm{d} x+z^3 \mathrm{d} x \mathrm{d} y\\
&=3 \iiint\limits_{\Omega}\left(x^2+y^2+z^2\right) \mathrm{d} v \\
& =3 \int_0^{2 \pi} \mathrm{d} \theta \int_0^\pi \mathrm{d} \varphi \int_0^1 r^4 \sin \varphi \mathrm{d} r \\
&=\frac{6 \pi}{5} \int_0^\pi \sin \varphi \mathrm{d} \varphi=\frac{12 \pi}{5}
\end{aligned}
$$

